        _lang() {
            return (window.mySimulation && window.mySimulation.lang) ? window.mySimulation.lang : 'en';
        }

        _pick(en, es) {
            return this._lang() === 'es' ? es : en;
        }

        _t(key) {
            return (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t(key) : key;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    trust: 50,
                    culturalReading: 0,
                    faceManagement: 0,
                    communicationCalibration: 0,
                    processCompetence: 0,
                    trustHistory: [],
                    randomEventIndex: Math.floor(Math.random() * 6),
                    eventHandled: false,
                    dealRevealed: false
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {};
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var currentPeriod = window.mySimulation.state.currentPeriod || 1;
            var roundIdx = Math.min(currentPeriod - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];
            var area = document.getElementById('decisionsArea');
            var allSelected = true;

            for (var i = 0; i < round.decisions.length; i++) {
                var dec = round.decisions[i];
                var selected = document.querySelector('input[name="' + dec.id + '"]:checked');
                if (!selected) {
                    allSelected = false;
                } else {
                    var optIdx = parseInt(selected.value);
                    decisions[dec.id] = {
                        value: dec.options[optIdx].value,
                        trust: dec.options[optIdx].trust,
                        dims: dec.options[optIdx].dims || {}
                    };
                }
            }

            var evtPanel = document.getElementById('eventPanel');
            if (evtPanel && evtPanel.style.display !== 'none') {
                var evtSelected = document.querySelector('input[name="eventChoice"]:checked');
                if (!evtSelected) {
                    allSelected = false;
                } else {
                    var evtIdx = parseInt(evtSelected.value);
                    var evt = this.RANDOM_EVENTS[window.mySimulation.state.domainState.randomEventIndex];
                    if (evt) {
                        decisions.eventChoice = {
                            value: evt.options[evtIdx].value,
                            trust: evt.options[evtIdx].trust,
                            dims: evt.options[evtIdx].dims || {}
                        };
                    }
                }
            }

            if (!allSelected) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('selection_warning'), 'warning'
                );
                return false;
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions || {};
            var totalTrustChange = 0;
            var dimChanges = { cultural: 0, face: 0, comm: 0, process: 0 };

            // Score only the decisions of the round being submitted. The framework (platform and Open player)
            // never clears state.decisions between rounds, so it still holds every earlier round and the
            // Round 3 event answer; summing all of it counted Round 1 four times and Round 3 twice.
            // Saved games keep working: older keys are simply not read.
            var period = parseInt(state.currentPeriod, 10) || 1;
            var roundDecs = this.ROUNDS[Math.max(0, Math.min(period - 1, this.ROUNDS.length - 1))].decisions;
            var roundKeys = [];
            for (var rk = 0; rk < roundDecs.length; rk++) { roundKeys.push(roundDecs[rk].id); }
            if (period === 3) { roundKeys.push('eventChoice'); }

            for (var ki = 0; ki < roundKeys.length; ki++) {
                var key = roundKeys[ki];
                if (d.hasOwnProperty(key) && d[key] && typeof d[key].trust === 'number') {
                    totalTrustChange += d[key].trust;
                    var dims = d[key].dims || {};
                    for (var dk in dims) {
                        if (dims.hasOwnProperty(dk)) {
                            dimChanges[dk] = (dimChanges[dk] || 0) + dims[dk];
                        }
                    }
                }
            }

            state.domainState.trust = Math.max(0, Math.min(100, state.domainState.trust + totalTrustChange));
            state.domainState.culturalReading += (dimChanges.cultural || 0);
            state.domainState.faceManagement += (dimChanges.face || 0);
            state.domainState.communicationCalibration += (dimChanges.comm || 0);
            state.domainState.processCompetence += (dimChanges.process || 0);
            state.domainState.trustHistory.push(state.domainState.trust);

            // platform score is domainState.trust, the Partnership Readiness Index, already 0-100 and
            // the same value getPerformanceSummary reads as finalTrust for the performance verdict
            var overallScore = Math.max(0, Math.min(100, Math.round(state.domainState.trust)));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore });

            var dealTerms = null;
            if (state.currentPeriod >= 4) {
                state.domainState.dealRevealed = true;
                dealTerms = this._getDealTerms(state.domainState.trust);
            }

            var _cr = state.currentPeriod;
            var self = this;
            setTimeout(function() {
                // a round undone before this timer runs keeps its own questions on screen
                var live = window.mySimulation && window.mySimulation.state;
                if (live && live.history && live.history.length < _cr) { return; }
                self._updateBriefing({ currentPeriod: _cr + 1, domainState: state.domainState });
                if (dealTerms) {
                    self._showDealOutcome(dealTerms, state.domainState.trust);
                }
            }, 500);

            return {
                period: state.currentPeriod,
                trustChange: totalTrustChange,
                trustTotal: state.domainState.trust,
                culturalReading: dimChanges.cultural || 0,
                faceManagement: dimChanges.face || 0,
                communicationCalibration: dimChanges.comm || 0,
                processCompetence: dimChanges.process || 0,
                dealTerms: dealTerms
            };
        }

