        _showDealOutcome(terms, trust) {
            var panel = document.getElementById('dealOutcomePanel');
            var textEl = document.getElementById('dealOutcomeText');
            if (panel && textEl) {
                panel.style.display = 'block';
                var statusLabel = this._pick(terms.statusEn, terms.statusEs);
                textEl.innerHTML = '<div style="text-align:center;margin-bottom:15px;">' +
                    '<div style="font-size:2.5rem;font-weight:700;color:#2c5f8a;">' + trust + '/100</div>' +
                    '<div style="font-size:1.1rem;color:#666;">' + statusLabel + '</div></div>' +
                    '<table class="table table-bordered" style="margin-top:15px;">' +
                    '<tr><td><strong>' + window.mySimulation.t('deal_revenue') + '</strong></td><td>' + this._pick(terms.revenueShareEn, terms.revenueShareEs) + '</td></tr>' +
                    '<tr><td><strong>' + window.mySimulation.t('deal_territory') + '</strong></td><td>' + this._pick(terms.territoryEn, terms.territoryEs) + '</td></tr>' +
                    '<tr><td><strong>' + window.mySimulation.t('deal_ip') + '</strong></td><td>' + this._pick(terms.ipLicenseEn, terms.ipLicenseEs) + '</td></tr>' +
