        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('trustDisplay', 'domainState.trust',
                (v) => Math.round(v) + '/100');
            uiManager.bind('culturalReadingDisplay', 'domainState.culturalReading',
                (v) => (v >= 0 ? '+' : '') + v);
            uiManager.bind('faceMgmtDisplay', 'domainState.faceManagement',
                (v) => (v >= 0 ? '+' : '') + v);
            uiManager.bind('commCalibDisplay', 'domainState.communicationCalibration',
                (v) => (v >= 0 ? '+' : '') + v);
            uiManager.bind('processCompDisplay', 'domainState.processCompetence',
                (v) => (v >= 0 ? '+' : '') + v);

            // An undo sends the player back to the round it removed, but the questions are drawn only by the timer
            // that follows a submission, so the screen kept the next round and the undone round could not be
            // answered again. Redraw the current round, and hide the deal terms until round 4 is scored again.
            // The framework input restore ran on the old buttons; running it again on the new ones also lets the
            // shared option-order block prepare them before the player answers.
            var self = this;
            var sim = window.mySimulation;
            if (sim && sim.eventBus && typeof sim.eventBus.on === 'function' && !this._undoBound) {
                this._undoBound = true;
                sim.eventBus.on('period:undone', function(st) {
                    var cur = st || sim.state;
                    self._updateBriefing(cur);
                    var dealPanel = document.getElementById('dealOutcomePanel');
                    if (dealPanel && !(cur.domainState && cur.domainState.dealRevealed)) {
                        dealPanel.style.display = 'none';
                    }
                    if (typeof sim.restoreInputValues === 'function') { sim.restoreInputValues(); }
                });
            }
        }

